insert into public.support_messages(state, text) values ('self_esteem', 'Tem dias em que a gente se vê com lentes mais duras. Isso não é a verdade inteira sobre você.');
insert into public.support_messages(state, text) values ('self_esteem', 'Sentir-se mal consigo não é falha sua. É um dia pesado, e ele passa.');
insert into public.support_messages(state, text) values ('self_esteem', 'Você não precisa se convencer de nada agora. Só se tratar com um pouco mais de gentileza.');
insert into public.support_messages(state, text) values ('self_esteem', 'O que você sente hoje é real. O que você vale não muda com ele.');
insert into public.support_messages(state, text) values ('self_esteem', 'Se uma amiga dissesse isso dela mesma, você seria gentil. Tenta ser assim com você.');
insert into public.support_messages(state, text) values ('self_esteem', 'Hoje não precisa ser o dia de gostar de tudo em você. Basta não se atacar.');
insert into public.support_messages(state, text) values ('self_esteem', 'Esse incômodo merece cuidado, não cobrança.');
insert into public.support_messages(state, text) values ('self_esteem', 'Você continua sendo a mesma pessoa que alguém admira em silêncio todo dia.');
insert into public.support_messages(state, text) values ('self_esteem', 'Tudo bem não se sentir bem. Fica aqui um lembrete do que você já construiu.');
insert into public.support_messages(state, text) values ('self_esteem', 'Quando a cabeça aperta, o corpo pede descanso, não julgamento.');
insert into public.support_messages(state, text) values ('self_esteem', 'Você não está atrasada em nada. Está vivendo um dia difícil.');
insert into public.support_messages(state, text) values ('self_esteem', 'Coisas boas que você fez continuam valendo, mesmo quando você não lembra delas.');
insert into public.support_messages(state, text) values ('self_esteem', 'Respira. Esse pensamento cruel não precisa ganhar a conversa hoje.');
insert into public.support_messages(state, text) values ('self_esteem', 'Você merece o mesmo carinho que oferece para quem ama.');
insert into public.support_messages(state, text) values ('self_esteem', 'Hoje dá pra começar pequeno: uma coisa gentil por você.');
insert into public.support_messages(state, text) values ('self_esteem', 'Não tem nada para consertar em você agora. Só para acolher.');
insert into public.support_messages(state, text) values ('self_esteem', 'Dias assim confundem. Seu valor não entra nessa conta.');
insert into public.support_messages(state, text) values ('self_esteem', 'Você é mais do que o que está sentindo neste momento.');
insert into public.support_messages(state, text) values ('self_esteem', 'Se for pesado, deixa ser pesado. E deixa alguém chegar perto.');
insert into public.support_messages(state, text) values ('self_esteem', 'Você já atravessou dias assim antes. Esse também tem fim.');
insert into public.support_messages(state, text) values ('self_esteem', 'Ninguém precisa ser incrível o tempo todo. Você também não.');
insert into public.support_messages(state, text) values ('self_esteem', 'Seu jeito de cuidar, de rir, de pensar: tudo isso continua aí.');
insert into public.support_messages(state, text) values ('self_esteem', 'Se não der para se elogiar, tudo bem. Só não se diminua.');
insert into public.support_messages(state, text) values ('self_esteem', 'Esse olhar duro é cansaço falando, não você.');
insert into public.support_messages(state, text) values ('self_esteem', 'Hoje vale trocar o espelho por algo que te faça bem por dentro.');
insert into public.support_messages(state, text) values ('self_esteem', 'Você não precisa merecer descanso. Pode só descansar.');
insert into public.support_messages(state, text) values ('self_esteem', 'Coisas que te tornam você não têm nada a ver com um dia ruim.');
insert into public.support_messages(state, text) values ('self_esteem', 'Que tal guardar hoje uma lembrança de quando você se sentiu forte?');
insert into public.support_messages(state, text) values ('self_esteem', 'Você tem o direito de estar num dia meio torto.');
insert into public.support_messages(state, text) values ('self_esteem', 'Carinho com você mesma não é exagero. É necessário.');
insert into public.support_messages(state, text) values ('self_esteem', 'Amanhã pode parecer diferente. Hoje, pega leve.');
insert into public.support_messages(state, text) values ('self_esteem', 'Tem gente que te acha incrível exatamente do jeito que você é. Uma delas mora com você.');
insert into public.support_messages(state, text) values ('sad', 'Tá difícil hoje, e tudo bem estar assim.');
insert into public.support_messages(state, text) values ('sad', 'Não precisa explicar a tristeza. Ela pode só existir um pouco.');
insert into public.support_messages(state, text) values ('sad', 'Você não tem que resolver nada agora. Só respirar.');
insert into public.support_messages(state, text) values ('sad', 'Que bom que você contou. Isso já é um cuidado com você.');
insert into public.support_messages(state, text) values ('sad', 'Dias tristes não pedem pressa. Pedem colo, água e tempo.');
insert into public.support_messages(state, text) values ('sad', 'Chorar, ficar quieta, deitar: tudo isso vale.');
insert into public.support_messages(state, text) values ('sad', 'Esse peso não é para carregar sozinha.');
insert into public.support_messages(state, text) values ('sad', 'Não existe jeito certo de passar por um dia ruim.');
insert into public.support_messages(state, text) values ('sad', 'Às vezes o melhor que dá para fazer é atravessar. Já é muito.');
insert into public.support_messages(state, text) values ('sad', 'Você pode pedir companhia ou pedir silêncio. Os dois são válidos.');
insert into public.support_messages(state, text) values ('sad', 'Tristeza não é fraqueza. É sinal de que algo importa.');
insert into public.support_messages(state, text) values ('sad', 'Se der, faz uma coisa pequena e gentil por você. Se não der, tudo bem também.');
insert into public.support_messages(state, text) values ('sad', 'Hoje não precisa render. Precisa só ser leve com você.');
insert into public.support_messages(state, text) values ('sad', 'Isso que você sente faz sentido, mesmo sem motivo claro.');
insert into public.support_messages(state, text) values ('sad', 'Tem dias em que a gente só precisa ser abraçada pelo dia acabar.');
insert into public.support_messages(state, text) values ('sad', 'Respira devagar. Um minuto de cada vez.');
insert into public.support_messages(state, text) values ('sad', 'Não tem problema ficar mal. Problema é ficar sozinha com isso.');
insert into public.support_messages(state, text) values ('sad', 'Você não precisa sorrir para ninguém hoje.');
insert into public.support_messages(state, text) values ('sad', 'Se o mundo estiver barulhento, você pode diminuir o volume.');
insert into public.support_messages(state, text) values ('sad', 'Seu sentimento é bem-vindo aqui do jeito que ele vier.');
insert into public.support_messages(state, text) values ('sad', 'Um dia ruim não apaga quem você é.');
insert into public.support_messages(state, text) values ('sad', 'Deixa o que der para depois. Hoje é dia de se cuidar.');
insert into public.support_messages(state, text) values ('sad', 'Que tal uma água, uma coberta e nenhuma cobrança?');
insert into public.support_messages(state, text) values ('sad', 'Você está fazendo o suficiente só de estar aqui.');
insert into public.support_messages(state, text) values ('sad', 'Às vezes o corpo pede pausa antes da cabeça entender.');
insert into public.support_messages(state, text) values ('sad', 'Ninguém espera que você esteja bem o tempo todo.');
insert into public.support_messages(state, text) values ('sad', 'Não tenta se convencer de que não é nada. É alguma coisa, e merece atenção.');
insert into public.support_messages(state, text) values ('sad', 'Escolha o que precisa agora: perto de alguém ou um pouco de silêncio.');
insert into public.support_messages(state, text) values ('sad', 'Dias assim passam, mesmo quando parecem enormes.');
insert into public.support_messages(state, text) values ('sad', 'Você tem permissão para desacelerar.');
insert into public.support_messages(state, text) values ('sad', 'Esse aperto não define o resto da semana.');
insert into public.support_messages(state, text) values ('sad', 'Alguém que te ama está a um toque de distância.');
insert into public.support_messages(state, text) values ('irritated', 'Irritação é sinal de limite. Faz sentido querer espaço.');
insert into public.support_messages(state, text) values ('irritated', 'Você não precisa justificar que está sem paciência hoje.');
insert into public.support_messages(state, text) values ('irritated', 'Tá tudo te tocando mais forte agora, e isso é real.');
insert into public.support_messages(state, text) values ('irritated', 'Pedir espaço é um jeito de cuidar da relação, não de fugir dela.');
insert into public.support_messages(state, text) values ('irritated', 'Antes de responder qualquer coisa, sessenta segundos só seus.');
insert into public.support_messages(state, text) values ('irritated', 'Ansiedade acelera tudo. Vamos desacelerar a respiração primeiro.');
insert into public.support_messages(state, text) values ('irritated', 'Não precisa resolver o que te irritou agora. Só baixar a temperatura.');
insert into public.support_messages(state, text) values ('irritated', 'Você pode estar irritada e continuar sendo carinhosa. Uma coisa não anula a outra.');
insert into public.support_messages(state, text) values ('irritated', 'Barulho demais por dentro? Diminui o de fora por um tempo.');
insert into public.support_messages(state, text) values ('irritated', 'Tá tudo bem querer ficar na sua hoje.');
insert into public.support_messages(state, text) values ('irritated', 'Seu limite merece respeito, inclusive o seu próprio.');
insert into public.support_messages(state, text) values ('irritated', 'Não precisa engolir o que sente. Só escolher a hora de falar.');
insert into public.support_messages(state, text) values ('irritated', 'Um copo d''água e cinco respirações longas já mudam um pouco.');
insert into public.support_messages(state, text) values ('irritated', 'Dias de pavio curto acontecem. Não é defeito de caráter.');
insert into public.support_messages(state, text) values ('irritated', 'Se for ansiedade, nomeia três coisas que você está vendo agora.');
insert into public.support_messages(state, text) values ('irritated', 'Você não está exagerando por se sentir assim.');
insert into public.support_messages(state, text) values ('irritated', 'Às vezes o melhor carinho é um pouco de distância.');
insert into public.support_messages(state, text) values ('irritated', 'Respira antes de decidir. A decisão espera um minuto.');
insert into public.support_messages(state, text) values ('irritated', 'O que te irrita hoje pode pesar menos amanhã. Ou não. As duas coisas são ok.');
insert into public.support_messages(state, text) values ('irritated', 'Avisar que precisa de espaço evita muita briga desnecessária.');
insert into public.support_messages(state, text) values ('irritated', 'Se o corpo estiver tenso, solta os ombros e o maxilar.');
insert into public.support_messages(state, text) values ('irritated', 'Ninguém precisa ter paciência infinita. Você também não.');
insert into public.support_messages(state, text) values ('irritated', 'Pode ser o dia, pode ser o ciclo, pode ser a vida. Não precisa saber agora.');
insert into public.support_messages(state, text) values ('irritated', 'Fica com o que te acalma: música, banho, silêncio.');
insert into public.support_messages(state, text) values ('irritated', 'Você tem o direito de não querer conversa agora.');
insert into public.support_messages(state, text) values ('irritated', 'Ansiedade mente sobre o tamanho das coisas. Dá um passo de cada vez.');
insert into public.support_messages(state, text) values ('irritated', 'Põe o celular de lado por cinco minutos, se der.');
insert into public.support_messages(state, text) values ('irritated', 'Irritação passa mais rápido quando é respeitada, não quando é engolida.');
insert into public.support_messages(state, text) values ('irritated', 'Não precisa ser a melhor versão de você hoje. Só uma versão honesta.');
insert into public.support_messages(state, text) values ('irritated', 'Um minuto respirando agora vale mais que dez explicando depois.');
insert into public.support_messages(state, text) values ('irritated', 'Você pode pedir espaço sem dar motivo. É só um aviso.');
insert into public.support_messages(state, text) values ('irritated', 'Cuida de você primeiro. O resto espera.');
insert into public.support_messages(state, text) values ('tired', 'Cansaço é recado do corpo. Escuta ele hoje.');
