insert into public.support_messages(state, text) values ('tired', 'Corpo cansado pede conforto, não cobrança.');
insert into public.support_messages(state, text) values ('tired', 'Hoje vale roupa confortável, coberta e nada de pressa.');
insert into public.support_messages(state, text) values ('tired', 'Você não está devendo energia a ninguém.');
insert into public.support_messages(state, text) values ('tired', 'Cólica, dor de cabeça, sono ruim: tudo isso conta. Pega leve.');
insert into public.support_messages(state, text) values ('tired', 'Pedir ajuda com a casa hoje é justo.');
insert into public.support_messages(state, text) values ('tired', 'Às vezes descansar é a coisa mais produtiva do dia.');
insert into public.support_messages(state, text) values ('tired', 'Um chá quente e dez minutos parada. Já ajuda.');
insert into public.support_messages(state, text) values ('tired', 'Não precisa ser forte o dia todo.');
insert into public.support_messages(state, text) values ('tired', 'Se o corpo pedir silêncio, dá silêncio pra ele.');
insert into public.support_messages(state, text) values ('tired', 'Nada do que ficou para trás hoje define você.');
