insert into public.support_messages(state, text) values ('tired', 'Que tal deixar alguém cuidar de você um pouco?');
insert into public.support_messages(state, text) values ('tired', 'Se puder, troque uma obrigação por um cochilo.');
insert into public.support_messages(state, text) values ('tired', 'Seu ritmo de hoje é o ritmo certo para hoje.');
insert into public.support_messages(state, text) values ('tired', 'Calor na barriga, água por perto e o resto pode esperar.');
insert into public.support_messages(state, text) values ('tired', 'Você já fez muito só de levantar.');
insert into public.support_messages(state, text) values ('tired', 'Desliga as notificações por um tempo. O mundo segura as pontas.');
insert into public.support_messages(state, text) values ('tired', 'Dor não é frescura. Merece cuidado de verdade.');
insert into public.support_messages(state, text) values ('tired', 'Hoje é dia de tarefas pela metade, e está tudo certo.');
insert into public.support_messages(state, text) values ('tired', 'Escolha uma coisa só para fazer hoje. Uma.');
insert into public.support_messages(state, text) values ('tired', 'Se for dia de sofá, que seja um sofá gostoso.');
insert into public.support_messages(state, text) values ('tired', 'Ninguém precisa render no mesmo nível todos os dias.');
insert into public.support_messages(state, text) values ('tired', 'Seu descanso também é um jeito de cuidar de quem você ama.');
insert into public.support_messages(state, text) values ('tired', 'Respira fundo, solta devagar, e diminui o passo.');
